var paths=UnityEditor.AssetDatabase.FindAssets("t:Material",new[]{"Assets/Art/Environments/Town02","Assets/Art/Environments/Hideout02","Assets/Art/Environments/TownProps02","Assets/ChibiSurvivor"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).Where(p=>p.EndsWith(".mat")).ToArray();
var rows=paths.Select(p=>{var m=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(p);return new{path=p,shader=m.shader.name,keywords=m.shaderKeywords,floats=new[]{"_Metallic","_Smoothness","_BumpScale","_GrimeStrength","_ShadowDesaturation","_RimStrength","_UsePackedMask","_OcclusionStrength"}.Where(m.HasProperty).ToDictionary(k=>k,k=>m.GetFloat(k)),textures=new[]{"_BaseMap","_BumpMap","_MetallicGlossMap","_OcclusionMap"}.Where(m.HasProperty).ToDictionary(k=>k,k=>UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture(k)))};}).ToArray();
